#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
    vector<int>target={0,0,0,1};
    vector<double>prob={0.1,0.2,0.3,0.6};
    double loss=0;
    for (int i=0;i<int(target.size());i++){
        double weight=target[i]?3.0:1.0;
