#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
    vector<vector<double>>factor={{1,0},{0.9,0.1},{0,1}};
    for (int i=0;i<3;i++)for (int j=i+1;j<3;j++){
        double similarity=0,normA=0,normB=0;
        for (int k=0;k<2;k++){
            similarity+=factor[i][k]*factor[j][k];
            normA+=pow(factor[i][k],2);
            normB+=pow(factor[j][k],2);
        }
        double cosine=similarity/sqrt(normA*normB);
        cout<<i<<" "<<j<<" "<<cosine<<"\n";
    }
    return 0;
}

